-- TallerPro V0.3: recursos exclusivos, claves compuestas por taller.
PRAGMA foreign_keys = ON;
CREATE TABLE companies (company_id TEXT PRIMARY KEY, name TEXT NOT NULL, settings_json TEXT NOT NULL CHECK(json_valid(settings_json)), revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (company_id TEXT NOT NULL, user_id TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','RECEPCION','TECNICO','CAJA')), PRIMARY KEY(company_id,user_id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE customers (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), name TEXT, document TEXT, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE technicians (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), name TEXT, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE products (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), sku TEXT, stock REAL CHECK(stock>=0), price REAL CHECK(price>=0), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE services (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), name TEXT, price REAL CHECK(price>=0), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE vehicles (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), customer_id TEXT, plate_normalized TEXT, make TEXT, model TEXT, year REAL, mileage REAL CHECK(mileage>=0), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id), FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id));
CREATE TABLE work_orders (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), vehicle_id TEXT, customer_id TEXT, technician_id TEXT, status TEXT, number TEXT, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id), FOREIGN KEY(company_id,vehicle_id) REFERENCES vehicles(company_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id), FOREIGN KEY(company_id,technician_id) REFERENCES technicians(company_id,id));
CREATE TABLE quotes (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), vehicle_id TEXT, customer_id TEXT, work_order_id TEXT, status TEXT, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id), FOREIGN KEY(company_id,vehicle_id) REFERENCES vehicles(company_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id), FOREIGN KEY(company_id,work_order_id) REFERENCES work_orders(company_id,id));
CREATE TABLE appointments (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), vehicle_id TEXT, customer_id TEXT, technician_id TEXT, date TEXT, time TEXT, status TEXT, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id), FOREIGN KEY(company_id,vehicle_id) REFERENCES vehicles(company_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id), FOREIGN KEY(company_id,technician_id) REFERENCES technicians(company_id,id));
CREATE TABLE sales (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), vehicle_id TEXT, customer_id TEXT, number TEXT, method TEXT, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id), FOREIGN KEY(company_id,vehicle_id) REFERENCES vehicles(company_id,id), FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id));
CREATE TABLE inventory_movements (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), product_id TEXT, quantity REAL, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id), FOREIGN KEY(company_id,product_id) REFERENCES products(company_id,id));
CREATE TABLE activity (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE UNIQUE INDEX vehicles_plate_tenant ON vehicles(company_id,plate_normalized);
CREATE UNIQUE INDEX customers_document_tenant ON customers(company_id,document);
CREATE UNIQUE INDEX products_sku_tenant ON products(company_id,sku);
CREATE UNIQUE INDEX orders_number_tenant ON work_orders(company_id,number);
CREATE UNIQUE INDEX sales_number_tenant ON sales(company_id,number);
CREATE INDEX orders_vehicle ON work_orders(company_id,vehicle_id);
CREATE INDEX appointments_technician_date ON appointments(company_id,technician_id,date);
CREATE TABLE receptions (company_id TEXT NOT NULL, id TEXT NOT NULL, work_order_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,work_order_id) REFERENCES work_orders(company_id,id) ON DELETE CASCADE);
CREATE INDEX receptions_parent ON receptions(company_id,work_order_id);
CREATE TABLE work_order_items (company_id TEXT NOT NULL, id TEXT NOT NULL, work_order_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,work_order_id) REFERENCES work_orders(company_id,id) ON DELETE CASCADE);
CREATE INDEX work_order_items_parent ON work_order_items(company_id,work_order_id);
CREATE TABLE vehicle_history (company_id TEXT NOT NULL, id TEXT NOT NULL, work_order_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,work_order_id) REFERENCES work_orders(company_id,id) ON DELETE CASCADE);
CREATE INDEX vehicle_history_parent ON vehicle_history(company_id,work_order_id);
CREATE TABLE quote_items (company_id TEXT NOT NULL, id TEXT NOT NULL, quote_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,quote_id) REFERENCES quotes(company_id,id) ON DELETE CASCADE);
CREATE INDEX quote_items_parent ON quote_items(company_id,quote_id);
CREATE TABLE sale_items (company_id TEXT NOT NULL, id TEXT NOT NULL, sale_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,sale_id) REFERENCES sales(company_id,id) ON DELETE CASCADE);
CREATE INDEX sale_items_parent ON sale_items(company_id,sale_id);
CREATE TABLE reminders (company_id TEXT NOT NULL, id TEXT NOT NULL, vehicle_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,vehicle_id) REFERENCES vehicles(company_id,id) ON DELETE CASCADE);
CREATE INDEX reminders_parent ON reminders(company_id,vehicle_id);
CREATE TABLE vehicle_documents (company_id TEXT NOT NULL, id TEXT NOT NULL, vehicle_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,vehicle_id) REFERENCES vehicles(company_id,id) ON DELETE CASCADE);
CREATE INDEX vehicle_documents_parent ON vehicle_documents(company_id,vehicle_id);
CREATE TABLE vehicle_photos (company_id TEXT NOT NULL, id TEXT NOT NULL, vehicle_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,vehicle_id) REFERENCES vehicles(company_id,id) ON DELETE CASCADE);
CREATE INDEX vehicle_photos_parent ON vehicle_photos(company_id,vehicle_id);
CREATE TABLE reception_photos (company_id TEXT NOT NULL, id TEXT NOT NULL, reception_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,reception_id) REFERENCES receptions(company_id,id) ON DELETE CASCADE);
CREATE INDEX reception_photos_parent ON reception_photos(company_id,reception_id);
CREATE TABLE cash_sessions (company_id TEXT NOT NULL, id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE cash_movements (company_id TEXT NOT NULL, id TEXT NOT NULL, cash_session_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,cash_session_id) REFERENCES cash_sessions(company_id,id) ON DELETE CASCADE);
CREATE TABLE files (company_id TEXT NOT NULL, id TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, vehicle_id TEXT NOT NULL, reception_id TEXT, mime TEXT NOT NULL CHECK(mime IN ('image/jpeg','image/png','image/webp')), size INTEGER NOT NULL CHECK(size>0 AND size<=1500000), label TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,vehicle_id) REFERENCES vehicles(company_id,id), FOREIGN KEY(company_id,reception_id) REFERENCES receptions(company_id,id));
CREATE INDEX files_vehicle ON files(company_id,vehicle_id);
CREATE TABLE request_receipts (company_id TEXT NOT NULL, id TEXT NOT NULL, expected_revision INTEGER NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TRIGGER revision_guard BEFORE INSERT ON request_receipts WHEN (SELECT revision FROM companies WHERE company_id=NEW.company_id) != NEW.expected_revision BEGIN SELECT RAISE(ABORT,'REVISION_CONFLICT'); END;
CREATE TABLE seed_runs (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auth_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
